import fs from 'node:fs';
import {createAuditedHttp} from './provider-http.mjs';
import {transcribeCompatible,parseCompatibleTranscript} from '../asr-runtime/asr-protocol.mjs';
import {createPrivateCosSource,PRIVATE_COS_CONFIG} from '../asr-runtime/asr-private-cos.mjs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {execFileSync} from 'node:child_process';
const COMMIT='97eac7e35dc3e098a4d7fdde76cdca6dbfb691fd';
const ROOT="/Users/administrator/.local/share/zenithjoy/leadgen-api-candidates/composite-97eac7e35dc3-phone-caa47f8ba3ae/services/phone-adb-controller";
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function need(v,c){if(!v)throw Error(c);}
const why=d=>`technical_unknown:${d.stage}:${d.reason}`;
const evidence=(s,run)=>({company_id:s.company_id,tenant_id:s.tenant_id,version:s.version,product_ids:s.product_ids,policy_id:s.policy_id,run_id:run});
function matches(row,{context:c,decision:d,transcript,snapshot:s}){
 if(!row)return false;
 if(d.verdict==='unknown')return (row.judgment_status==='pending'&&row.judgment_reason===why(d))||['matched','rejected'].includes(row.judgment_status);
 const e=evidence(s,c.tasks['102'].run_tag),actual=row.judgment_config;
 return row.judgment_status===d.verdict&&row.judgment_reason===d.reason&&row.transcript===transcript&&actual&&Object.entries(e).every(([k,v])=>same(actual[k],v));
}
export async function commitWithOwner(input,{transaction,db,authority,pinnedSnapshot}={}){
 const {pool,context:c,video_id,decision:d,snapshot:s,transcript}=input;
 await authority();
 return transaction(pool,async client=>{
  const rows=(await client.query('SELECT video_id,process_status,judgment_status,judgment_reason,judgment_config,transcript FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND video_id=$2 FOR UPDATE',[c.line,video_id])).rows;
  need(rows.length===1&&rows[0].process_status==='处理中:'+c.tasks['102'].run_tag,'VIDEO_OWNER_CHANGED');
  if(pinnedSnapshot)await pinnedSnapshot(client,s);
  let res;
  if(d.verdict==='unknown'){
   if(rows[0].judgment_status==='pending')res=await db.markVideoJudgeError(client,{lineKey:c.line,videoId:video_id,reason:why(d),transcript});
  }else{
   need(['matched','rejected'].includes(d.verdict),'INVALID_VERDICT');
   res=await db.markVideoJudgment(client,{lineKey:c.line,videoId:video_id,verdict:d.verdict,reason:d.reason,transcript,configEvidence:evidence(s,c.tasks['102'].run_tag)});
  }
  if(res)need(res.rowCount===1,'COMMIT_ROWCOUNT');
  const after=(await client.query('SELECT video_id,process_status,judgment_status,judgment_reason,judgment_config,transcript FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND video_id=$2',[c.line,video_id])).rows;
  need(after.length===1&&after[0].process_status==='处理中:'+c.tasks['102'].run_tag&&matches(after[0],input),'COMMIT_READBACK_UNVERIFIED');
  return {verified:true};
 });
}
export function createRuntimeDeps(c){
 need(c.source_commit===COMMIT&&c.runtime_root===ROOT&&fs.realpathSync(ROOT)===ROOT,'RUNTIME_NOT_PINNED');
 need(typeof c.actor==='string'&&c.actor.length>0,'CONTEXT_ACTOR_REQUIRED');
 const require=createRequire(ROOT+'/package.json');
 const asr=require('./transcribe-qwen-audio.js'),judge=require('./judge-jev.js'),company=require('./company-config-lib.js');
 const db=require('./leadgen-db-lib.js'),queue=require('./leadgen-queue.js'),pool=require('./leadgen-db-connect.js').getPool();
 const task=c.tasks['102'];
 const timeout=()=>{const n=c.business_deadline_ms-Date.now();need(n>0,'BUSINESS_DEADLINE');return Math.min(n,120000);};
 const readSnapshot=async client=>{
  const rows=(await client.query('SELECT company_id,tenant_id,version,run_id,snapshot FROM zenithjoy.company_config_runs WHERE company_id=$1 AND run_id=$2',[c.company_id,task.run_tag])).rows;
  const row=rows[0];need(rows.length===1&&row.tenant_id===c.tenant_id&&row.snapshot?.company_id===c.company_id&&row.snapshot?.tenant_id===c.tenant_id&&Number(row.version)===row.snapshot.version&&row.snapshot.config_status==='enabled'&&row.snapshot.runtime_config?.routing?.line_key===c.line,'FROZEN_POLICY_MISSING');
  need(Number.isSafeInteger(c.verification?.policy_version)&&c.verification.policy_version===Number(row.version)&&c.verification.policy_id===row.snapshot.runtime_config?.policy_id,'FROZEN_POLICY_VERSION');
  if(c.company_config_version!==undefined)need(Number(c.company_config_version)===c.verification.policy_version,'FROZEN_POLICY_VERSION');
  return company.runtimeSnapshot(row.snapshot,'102');
 };
 const authority=async()=>{
  timeout();const token=process.env.BRAIN_INTERNAL_TOKEN||process.env.CECELIA_INTERNAL_TOKEN;need(token,'BRAIN_CREDENTIAL_MISSING');
  for(const id of [...new Set([task.task_id,c.root_task_id].filter(Boolean))]){
   const response=await fetch('http://127.0.0.1:5221/api/brain/tasks/'+encodeURIComponent(id),{headers:{'X-Internal-Token':token},signal:AbortSignal.timeout(Math.min(timeout(),20000))});
   need(response.ok,'TASK_READ_FAILED');const raw=await response.json(),t=raw.task||raw;
   need(t.id===id&&t.status==='in_progress'&&t.claimed_by===c.actor,'TASK_AUTHORITY_CHANGED');
  }
 };
 const http=(stage,audit)=>createAuditedHttp({stage,audit,timeout});
 return {now:Date.now,authority,freeze:async()=>{const s=await readSnapshot(pool);await verifyLivePolicy(pool,c,s);return s;},
  validateAudio(audio){const v=JSON.parse(execFileSync('ffprobe',['-v','error','-show_entries','format=duration:stream=codec_type','-of','json',audio],{encoding:'utf8',timeout:20000,maxBuffer:1024*1024}));need(v.streams?.some(x=>x.codec_type==='audio'),'AUDIO_STREAM_MISSING');return {duration:Number(v.format?.duration)};},
  asr:(audio,{audit})=>{
   const ids=c.verification?.['102']?.video_ids;need(Array.isArray(ids)&&ids.length===1,'ASR_VIDEO_SCOPE');
   const source=createPrivateCosSource({config:PRIVATE_COS_CONFIG,scope:{task_id:task.task_id,run_id:task.run_id,action_id:'qualification-asr',video_id:ids[0],owner:c.actor,audio_sha256:createHash('sha256').update(fs.readFileSync(audio)).digest('hex')},journalPath:path.join(path.dirname(c.skills_root),'qualification-receipts',ids[0],'cos-source.json'),deadlineMs:c.business_deadline_ms,credentials:{SecretId:process.env.COS_SECRET_ID,SecretKey:process.env.COS_SECRET_KEY}});
   return transcribeCompatible(audio,{legacyAsr:asr,source,apiKey:process.env.DASHSCOPE_API_KEY,audit});
  },
  judge:(text,snapshot,{audit})=>judge.judgePrimary(text,company.configTargetProfile(snapshot,'102'),{httpPost:http('judge',audit)}),
  recoverAsr:r=>r.http_status===200?parseCompatibleTranscript(r.body):null,
  recoverJudge:(text,snapshot,r)=>r.http_status===200?judge.judgePrimary(text,company.configTargetProfile(snapshot,'102'),{apiKey:'offline-response-replay',httpPost:async()=>r.body}):{verdict:'UNCERTAIN',reason:'saved_provider_error'},
  commit:input=>commitWithOwner({...input,pool},{transaction:queue.transaction,db,authority,pinnedSnapshot:async(client,s)=>{need(same(await readSnapshot(client),s),'FROZEN_POLICY_CHANGED');await verifyLivePolicy(client,c,s);}}),
  readback:async input=>{const rows=(await pool.query('SELECT video_id,process_status,judgment_status,judgment_reason,judgment_config,transcript FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND video_id=$2',[c.line,input.video_id])).rows;return {verified:rows.length===1&&matches(rows[0],input)};},
  close:()=>pool.end()
 };
}
export async function verifyLivePolicy(client,c,snapshot){
 const v=c.verification;
 need(Number.isSafeInteger(v?.policy_version)&&v.policy_version>0&&typeof v.policy_id==='string'&&v.policy_id.length>0,'LIVE_POLICY_CHANGED');
 const rows=(await client.query("SELECT company_id,tenant_id,config_status,config_version,runtime_config->>'policy_id' AS policy_id FROM zenithjoy.tenant_company_profiles WHERE company_id=$1 FOR SHARE",[c.company_id])).rows;
 const r=rows[0];
 need(rows.length===1&&r.company_id===c.company_id&&r.tenant_id===c.tenant_id&&r.config_status==='enabled'&&Number(r.config_version)===v.policy_version&&r.policy_id===v.policy_id&&snapshot.company_id===c.company_id&&snapshot.tenant_id===c.tenant_id&&snapshot.version===v.policy_version&&snapshot.policy_id===v.policy_id,'LIVE_POLICY_CHANGED');
 return true;
}

