import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {createRuntimeDeps} from './runtime-deps.mjs';
import {acquireProcessLock} from './process-lock.mjs';
const hash=value=>crypto.createHash('sha256').update(value).digest('hex');
const canonical=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b))):x);
function need(v,code){if(!v)throw Error(code);}
function save(file,value){
 const tmp=file+'.'+crypto.randomUUID()+'.tmp';const fd=fs.openSync(tmp,'wx',0o600);
 try{fs.writeFileSync(fd,JSON.stringify(value,null,2)+'\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}
 fs.renameSync(tmp,file);const dir=fs.openSync(path.dirname(file),'r');try{fs.fsyncSync(dir);}finally{fs.closeSync(dir);}
}
function asset(file){return fs.existsSync(file)?{path:file,sha256:hash(fs.readFileSync(file))}:null;}
function privateDir(dir){
 need(path.isAbsolute(dir),'ARTIFACT_PATH_INVALID');fs.mkdirSync(dir,{recursive:true,mode:0o700});
 const st=fs.lstatSync(dir);need(st.isDirectory()&&!st.isSymbolicLink()&&fs.realpathSync(dir)===path.resolve(dir)&&st.uid===process.getuid()&&(st.mode&0o777)===0o700,'ARTIFACT_PATH_UNTRUSTED');
}
/** 每个artifact_dir只容纳一个冻结VID；恢复不重新发送未知外部调用。 */
export async function main({context:c,video_id,audio,artifact_dir},injectedDeps){
 const task=c?.tasks?.['102'];need(task?.task_id&&task.run_id&&task.run_tag&&/^\d{16,24}$/.test(video_id||''),'QUALIFICATION_SCOPE');
 need(c.company_id&&c.tenant_id&&c.line&&/^[a-f0-9]{40}$/.test(c.source_commit||''),'CONTEXT_SCOPE');
 need(path.isAbsolute(audio)&&!fs.lstatSync(audio).isSymbolicLink()&&fs.realpathSync(audio)===path.resolve(audio),'AUDIO_PATH_INVALID');
 privateDir(artifact_dir);const lock=path.join(artifact_dir,'active.lock');
 const held=await acquireProcessLock(lock);
 let deps;
 try{
  deps=injectedDeps||createRuntimeDeps(c);const now=deps.now||Date.now;
  need(Number.isFinite(c.business_deadline_ms)&&now()<c.business_deadline_ms,'BUSINESS_DEADLINE');
  const audioSha=hash(fs.readFileSync(audio));const scope={task_id:task.task_id,run_id:task.run_id,run:task.run_tag,company_id:c.company_id,tenant_id:c.tenant_id,line:c.line,source_commit:c.source_commit,video_id,audio_sha256:audioSha};
  const journal=path.join(artifact_dir,'journal.json'),asrFile=path.join(artifact_dir,'asr-response.json'),judgeFile=path.join(artifact_dir,'judge-response.json');
  let j=fs.existsSync(journal)?JSON.parse(fs.readFileSync(journal,'utf8')):{schema_version:1,scope,phase:'new',calls:{asr:0,judge:0},started_at:new Date(now()).toISOString()};
  need(canonical(j.scope)===canonical(scope),'JOURNAL_SCOPE_CHANGED');
  held.assertHeld();await deps.authority();const snapshot=await deps.freeze();
  need(snapshot.company_id===c.company_id&&snapshot.tenant_id===c.tenant_id&&snapshot.policy_id&&Number.isSafeInteger(snapshot.version),'POLICY_SCOPE');
  const policySha=hash(canonical(snapshot));need(!j.policy_sha256||j.policy_sha256===policySha,'FROZEN_POLICY_CHANGED');
  j.policy_sha256=policySha;j.policy={company_id:snapshot.company_id,tenant_id:snapshot.tenant_id,version:snapshot.version,policy_id:snapshot.policy_id};
  const flush=()=>save(journal,j);
  const unknown=(reason,stage)=>({verdict:'unknown',reason,stage});
  const output=decision=>({...decision,task_id:task.task_id,run_id:task.run_id,video_id,policy:j.policy,calls:j.calls,call_semantics:'function_invocations; provider receipts prove actual HTTP outcomes',journal:asset(journal),native_artifacts:{asr:asset(asrFile),asr_audio_sha256:audioSha,judge:asset(judgeFile)}});
  const expected=()=>({context:c,video_id,snapshot,decision:j.decision,transcript:j.transcript||null});
  if(j.phase==='done'){
   const read=await deps.readback(expected());
   return output(read.verified?j.decision:unknown('PERSISTED_READBACK_UNCONFIRMED','readback'));
  }
  if(j.phase==='commit_started'){
   const read=await deps.readback(expected());
   if(read.verified){j.phase='done';flush();return output(j.decision);}
   return output(unknown('COMMIT_UNCONFIRMED','commit'));
  }
  if(j.phase==='asr_started'){
   if(fs.existsSync(asrFile)&&deps.recoverAsr){
    const text=await deps.recoverAsr(JSON.parse(fs.readFileSync(asrFile)));
    if(typeof text==='string'&&text.trim()){j.transcript=text;j.phase='asr_done';flush();}
   }
   if(j.phase==='asr_started'){j.decision=unknown('ASR_CALL_UNCONFIRMED','asr');j.phase='decided';flush();}
  }
  if(j.phase==='judge_started'){
   if(fs.existsSync(judgeFile)&&deps.recoverJudge){
    let v;try{v=await deps.recoverJudge(j.transcript,snapshot,JSON.parse(fs.readFileSync(judgeFile)));}catch{v={verdict:'UNCERTAIN'};}
    j.decision=mapJudgment(v);j.phase='decided';flush();
   }else{j.decision=unknown('MODEL_CALL_UNCONFIRMED','judge');j.phase='decided';flush();}
  }
  if(j.phase==='new'){
   const media=await deps.validateAudio(audio);need(media?.duration>0&&media.duration<=300,'AUDIO_DURATION_UNVERIFIED');
   if(c.qualification_coverage_seconds!=null)need(Number.isFinite(c.qualification_coverage_seconds)&&c.qualification_coverage_seconds>0&&c.qualification_coverage_seconds<=300&&media.duration>=c.qualification_coverage_seconds,'AUDIO_COVERAGE_UNVERIFIED');
   j.media=media;flush();
   held.assertHeld();await deps.authority();need(now()<c.business_deadline_ms,'BUSINESS_DEADLINE');
   need(hash(fs.readFileSync(audio))===audioSha,'AUDIO_CHANGED');
   j.phase='asr_started';j.calls.asr=1;flush();
   try{
    const text=await deps.asr(audio,{audit:r=>{need(!fs.existsSync(asrFile),'ASR_RECEIPT_DUPLICATE');save(asrFile,r);}});
    need(typeof text==='string'&&text.trim()&&fs.existsSync(asrFile),'ASR_UNVERIFIED');
    j.transcript=text;j.phase='asr_done';flush();
   }catch{j.decision=unknown('ASR_UNVERIFIED','asr');j.phase='decided';flush();}
  }
  if(j.phase==='asr_done'){
   held.assertHeld();await deps.authority();need(now()<c.business_deadline_ms,'BUSINESS_DEADLINE');
   j.phase='judge_started';j.calls.judge=1;flush();
   try{j.decision=mapJudgment(await deps.judge(j.transcript,snapshot,{audit:r=>{need(!fs.existsSync(judgeFile),'MODEL_RECEIPT_DUPLICATE');save(judgeFile,r);}}));}
   catch{j.decision=unknown('MODEL_UNVERIFIED','judge');}
   j.phase='decided';flush();
  }
  need(j.phase==='decided'&&j.decision,'JOURNAL_PHASE_INVALID');
  held.assertHeld();await deps.authority();need(now()<c.business_deadline_ms,'BUSINESS_DEADLINE');
  const frozenAgain=await deps.freeze();need(hash(canonical(frozenAgain))===j.policy_sha256,'FROZEN_POLICY_CHANGED');
  j.phase='commit_started';flush();
  try{const written=await deps.commit(expected());need(written?.verified,'COMMIT_READBACK_UNVERIFIED');}
  catch{return output(unknown('COMMIT_UNCONFIRMED','commit'));}
  const read=await deps.readback(expected());if(!read.verified)return output(unknown('COMMIT_UNCONFIRMED','commit'));
  j.phase='done';j.finished_at=new Date(now()).toISOString();flush();return output(j.decision);
 }finally{try{await deps?.close?.();}finally{await held.release();}}
}
function mapJudgment(v){
 if(v?.verdict==='MATCHED'||v?.verdict==='REJECTED'){
  need(typeof v.reason==='string'&&v.reason.trim(),'MODEL_REASON_MISSING');return {verdict:v.verdict.toLowerCase(),reason:v.reason,stage:'judge'};
 }
 return {verdict:'unknown',reason:'MODEL_UNCERTAIN',stage:'judge'};
}

