import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';import {execFileSync} from 'node:child_process';import crypto from 'node:crypto';
const ROOT='/Users/administrator/.local/share/zenithjoy/leadgen-api-candidates/composite-97eac7e35dc3-phone-caa47f8ba3ae/services/phone-adb-controller',COMMIT='97eac7e35dc3e098a4d7fdde76cdca6dbfb691fd';
const need=(v,c)=>{if(!v)throw Error(c);},hash=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
export async function createDeps(c,profileRoot){
 need(c.runtime_root===ROOT&&c.source_commit===COMMIT&&fs.realpathSync(ROOT)===ROOT,'RUNTIME_SCOPE');
 for(const file of ['queued-recipient-evidence.js','company-config-lib.js','line-routes.js','nickname-match-lib.js'])need(c.verification.runtime_sha256?.[file]===hash(path.join(ROOT,file)),'RUNTIME_PIN');
 need(process.env.DATABASE_URL,'PARENT_DATABASE_ENV');const require=createRequire(ROOT+'/package.json'),{Pool}=require('pg'),pool=new Pool({connectionString:process.env.DATABASE_URL,connectionTimeoutMillis:10000,max:1});const module=require('./queued-recipient-evidence.js'),company=require('./company-config-lib.js');
 return {
  async binding(){const client=await pool.connect();try{await client.query('BEGIN READ ONLY');await client.query("SET LOCAL statement_timeout='10000ms'");need((await client.query('SELECT current_database() AS name')).rows[0]?.name==='zenithjoy','WRONG_DATABASE');const value=await company.readCollectionAccountBinding(client,{lineKey:c.line,run:c.tasks['102'].run_tag,sourceRun:null});await client.query('ROLLBACK');return value;}finally{client.release();}},
  async verifyIdentity(spec){const p=c.verification.artifact_checker;need(p?.command?.length===2&&p.command[1]===path.join(profileRoot,'skills/douyin-leadgen-commander/scripts/native_artifacts.py')&&p.command.every(f=>p.sha256?.[f]===hash(f)),'NATIVE_CHECKER_PIN');const code="import importlib.util,sys,json\ns=importlib.util.spec_from_file_location('native_checker',sys.argv[1]);m=importlib.util.module_from_spec(s);s.loader.exec_module(m)\nprint(json.dumps({'verified':m.native_video_identity(json.load(sys.stdin))}))\n";return JSON.parse(execFileSync(p.command[0],['-c',code,p.command[1]],{input:JSON.stringify(spec),encoding:'utf8',timeout:30000,maxBuffer:1024*1024})).verified===true;},
  async capture(args,evidenceRoot){const previous=process.env.DOUYIN_PHONE_TMP_ROOT;try{process.env.DOUYIN_PHONE_TMP_ROOT=evidenceRoot;return module.capture(args);}finally{if(previous===undefined)delete process.env.DOUYIN_PHONE_TMP_ROOT;else process.env.DOUYIN_PHONE_TMP_ROOT=previous;}},
  close:()=>pool.end()
 };
